    public OpportunityService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new OpportunityEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(OpportunityRepository.class) );
		this.validator		= applicationContext.getBean(OpportunityValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Opportunity
	 */
		public Opportunity createOpportunity( CreateOpportunityCommand command ) {

		Opportunity entity = new Opportunity();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setOpportunityId( command.getOpportunityId() );
            entity.setName( command.getName() );
            entity.setAmount( command.getAmount() );
            entity.setCloseDate( command.getCloseDate() );
            entity.setProbability( command.getProbability() );
            entity.setDescription( command.getDescription() );
            entity.setStage( command.getStage() );
            entity.setType( command.getType() );
            entity.setForecastCategory( command.getForecastCategory() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Opportunity {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateOpportunityCommand
	 * @return		Opportunity
	 */
	public Opportunity updateOpportunity( UpdateOpportunityCommand command ) {

		Opportunity entity = new Opportunity();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setOpportunityId( command.getOpportunityId() );
            entity.setName( command.getName() );
            entity.setAmount( command.getAmount() );
            entity.setCloseDate( command.getCloseDate() );
            entity.setProbability( command.getProbability() );
            entity.setDescription( command.getDescription() );
            entity.setOrganization( command.getOrganization() );
            entity.setAccount( command.getAccount() );
            entity.setOwner( command.getOwner() );
            entity.setContacts( command.getContacts() );
            entity.setLineItems( command.getLineItems() );
            entity.setStageHistory( command.getStageHistory() );
            entity.setQuotes( command.getQuotes() );
            entity.setOrders( command.getOrders() );
            entity.setCampaigns( command.getCampaigns() );
            entity.setActivities( command.getActivities() );
            entity.setTeams( command.getTeams() );
            entity.setStage( command.getStage() );
            entity.setType( command.getType() );
            entity.setForecastCategory( command.getForecastCategory() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Opportunity {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteOpportunityCommand
	 */
	public void delete( DeleteOpportunityCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getOpportunityId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Opportunity {0} ", id );

	}

	/**
	 * Method to retrieve the Opportunity via OpportunityFetchOneSummary
	 * @param 	summary OpportunityFetchOneSummary
	 * @return 	OpportunityFetchOneResponse
	 */
	public Opportunity getOpportunity( OpportunityFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "OpportunityFetchOneSummary arg cannot be null" );

		Opportunity entity = null;
		UUID id = summary.getOpportunityId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Opportunity using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Opportunitys
	 *
	 * @return 	List<Opportunity>
	 */
    public List<Opportunity> getAllOpportunity() {
		List<Opportunity> list = projector.findAll( new FindAllOpportunityQuery() );
		return list;
	}

